    nodes: dict[tuple[int, int], bytes],
    leaves: dict[int, tuple[bytes, tuple[bytes, ...]]],
    index: int,
    level: int,
) -> bytes:
    """Look up one auth-path sibling of leaf ``index`` at ``level``.

    The sibling is either a carried canonical node from one of the source
    proofs or, when both children were proven together, an internal node that
    folds from known leaves and carried lower-level nodes.
    :func:`multiproof_merge` only reaches this helper after every source
    proof folded to the root, so the lookup always hits.
    """
