    node = nodes.get(coordinate)
    if node is not None:
        return node
    known: dict[tuple[int, int], bytes] = dict(nodes)
    w_for_hash = None  # placeholder replaced below
    raise RuntimeError("unreachable: a merged authentication node is missing")

